import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster } from "./tokens.stylex";
import { rs } from "./rs";

export interface SliderProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "type" | "value" | "defaultValue" | "onChange"> {
  value?: number;
  defaultValue?: number;
  min?: number;
  max?: number;
  step?: number;
  onValueChange?: (value: number) => void;
}

const styles = stylex.create({
  slider: {
    position: "relative",
    height: {
      default: 2,
      ["@media (max-width: 640px)"]: 4,
    },
    backgroundColor: raster.divider,
    borderRadius: {
      default: 1,
      ["@media (max-width: 640px)"]: 0,
    },
    marginBlock: {
      default: 10,
      ["@media (max-width: 640px)"]: 20,
    },
    marginInline: 0,
  },
  fill: {
    position: "absolute",
    left: 0,
    top: 0,
    bottom: 0,
    backgroundColor: raster.ink,
    borderRadius: {
      default: 1,
      ["@media (max-width: 640px)"]: 0,
    },
  },
  thumb: {
    position: "absolute",
    top: "50%",
    transform: "translate(-50%, -50%)",
    width: {
      default: 14,
      ["@media (max-width: 640px)"]: 22,
    },
    height: {
      default: 14,
      ["@media (max-width: 640px)"]: 22,
    },
    borderRadius: {
      default: "50%",
      ["@media (max-width: 640px)"]: 0,
    },
    backgroundColor: raster.paper,
    borderWidth: 1.5,
    borderStyle: "solid",
    borderColor: raster.ink,
    boxSizing: "border-box",
  },
  range: {
    position: "absolute",
    left: 0,
    right: 0,
    top: {
      default: -8,
      ["@media (max-width: 640px)"]: -20,
    },
    bottom: {
      default: -8,
      ["@media (max-width: 640px)"]: -20,
    },
    width: "100%",
    height: "auto",
    opacity: 0,
    cursor: "pointer",
    margin: 0,
  },
});

/** A native range input drives the ink track. */
export const Slider = React.forwardRef<HTMLInputElement, SliderProps>(function Slider(
  { value, defaultValue = 50, min = 0, max = 100, step = 1, onValueChange, className, style, ...props },
  ref,
) {
  const [inner, setInner] = React.useState(defaultValue);
  const isControlled = value !== undefined;
  const current = isControlled ? value : inner;
  const pct = max === min ? 0 : ((current - min) / (max - min)) * 100;
  const sx = rs(["rs-slider", className], styles.slider);
  const fill = rs(["rs-slider-fill"], styles.fill);
  const thumb = rs(["rs-slider-thumb"], styles.thumb);
  const range = rs([], styles.range);
  return (
    <div className={sx.className} style={{ ...sx.style, ...style }}>
      <span className={fill.className} style={{ ...fill.style, width: `${pct}%` }} />
      <span className={thumb.className} style={{ ...thumb.style, left: `${pct}%` }} />
      <input
        ref={ref}
        type="range"
        min={min}
        max={max}
        step={step}
        value={current}
        className={range.className}
        style={range.style}
        onChange={(e) => {
          const next = Number(e.target.value);
          if (!isControlled) setInner(next);
          onValueChange?.(next);
        }}
        {...props}
      />
    </div>
  );
});

import * as stylex from "@stylexjs/stylex";

/**
 * StyleX vars alias Raster CSS custom properties. Not a second scale.
 * Values live in packages/core/css/tokens.css (generated from src/tokens.ts).
 */
export const raster = stylex.defineVars({
  paper: "var(--bg)",
  ink: "var(--text)",
  gray: "var(--text-secondary)",
  accent: "var(--accent)",
  divider: "var(--divider)",
  dividerSubtle: "var(--divider-subtle)",
  tableAlt: "var(--table-alt)",
  gridLine: "var(--grid-line)",
  radiusSm: "var(--radius-sm)",
  radius: "var(--radius)",
  radiusChrome: "var(--radius-chrome)",
  radiusIn: "var(--radius-in)",
  pad: "var(--pad)",
  gutter: "var(--gutter)",
  module: "var(--grid-size)",
  gridImage: "var(--grid-image)",
  gridPos: "var(--grid-pos)",
  hit: "var(--hit)",
  controlH: "var(--control-h)",
  controlFs: "var(--control-fs)",
  controlLabel: "var(--control-label)",
  durationSnap: "var(--duration-snap)",
  duration: "var(--duration)",
  durationConfirm: "var(--duration-confirm)",
  ease: "var(--ease)",
  transition: "var(--transition)",
  textScale: "var(--text-scale)",
  hairline: "1px",
});

/** Inter stack. Same as body in base.css. Not a token var — @font-face stays CSS. */
export const rasterFont =
  "Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif";

export const rasterMono = "ui-monospace, SFMono-Regular, Menlo, monospace";

/** Compile-time media keys. StyleX only folds defineConsts, not plain strings. */
export const mq = stylex.defineConsts({
  phone: "@media (max-width: 640px)",
  mobileGrid: "@media (max-width: 480px)",
  at900: "@media (min-width: 900px)",
  at899: "@media (max-width: 899px)",
  rail: "@media (min-width: 1024px)",
  wide: "@media (min-width: 1440px)",
  reduce: "@media (prefers-reduced-motion: reduce)",
  touch: "@media (hover: none)",
});

/** Phone recut (≤640). Desktop stays the poster. */
export const phone = mq.phone;

/** Mobile grid (≤480). */
export const mobileGrid = mq.mobileGrid;

/** Catalog rail. */
export const rail = mq.rail;

/** Wide catalog. */
export const wide = mq.wide;

import type { CSSProperties } from "react";
import * as stylex from "@stylexjs/stylex";
import { cx } from "./cx";

type StyleXProps = { className?: string; style?: CSSProperties };

/** Merge Raster class names with StyleX props. CSS-first classes stay on the node. */
export function rs(classNames: Array<string | false | null | undefined>, ...styles: unknown[]): StyleXProps {
  const sx = (stylex.props as (...args: unknown[]) => StyleXProps)(...styles);
  return {
    className: cx(...classNames, sx.className),
    style: sx.style,
  };
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Slider: thin track with ink fill and 14px thumb ── */
.rs-slider{position:relative;height:2px;background:var(--divider);border-radius:1px;margin:10px 0}
.rs-slider-fill{position:absolute;left:0;top:0;bottom:0;background:var(--text);border-radius:1px}
.rs-slider-thumb{position:absolute;top:50%;transform:translate(-50%,-50%);width:14px;height:14px;border-radius:50%;background:var(--bg);border:1.5px solid var(--text)}
.rs-slider input[type=range]{position:absolute;left:0;right:0;top:-8px;bottom:-8px;width:100%;height:auto;opacity:0;cursor:pointer;margin:0}
.rs-slider:has(input[type=range]:focus-visible) .rs-slider-thumb{outline:1.5px solid var(--text);outline-offset:2px}
